function updateSpeedReadout(instruments,now){
  const knots=instruments.logKnots;
  if(!speedReadout){
    speedReadout={knots,sampledAt:now,drawnAt:null};
  }else{
    const elapsed=Math.max(0,now-speedReadout.sampledAt);
    // Smooth over time independently of frame rate or menu-triggered redraws.
    const previous=speedReadout.knots;
    speedReadout.knots=Number.isFinite(previous)&&Number.isFinite(knots)
      ?lerp(previous,knots,1-Math.exp(-elapsed/900)):knots;
    speedReadout.sampledAt=Math.max(now,speedReadout.sampledAt);
  }
  if(speedReadout.drawnAt!==null&&now-speedReadout.drawnAt<250)return;
  speedReadout.drawnAt=now;
  const speed=$('speed');
  setText(speed,fmt(speedReadout.knots).replace('.',','));
  speed.title='Fart relativt til middelstrømmen · Fart over grunden '+fmt(instruments.knots)+' knob';
}

