  const trimKeys=Number(haulPressed())-Number(easePressed()),cfg=P.configFor(state);
  const selected=state.boatId==='yacht'&&difficulty==='hard'?trimSail:'main';
  const time=clamp(env.controlRate??1,.35,2)*Sim.fixedDt;
  if(selected!=='main'&&trimKeys){
    const key=selected==='jib'?'jibSheet':'extraSheet';
    const sheet=rigCommand[key]??state.cruiserRig?.[key]??state.sheet;
    rigCommand[key]=sheet+P.limitSheetTravel(sheet,cfg,trimKeys*.5*time,time,selected==='extra');
  }
  const trimKey=selected==='main'?trimKeys:0,difference=sheetTarget-state.sheet;
  const trimFast=!!trimKey||(!cfg.rigidWing&&difference!==0);
  const trimRate=P.sheetRateFor(cfg,trimKey||difference,trimFast,difficulty);
  const travelLimit=trimRate*time;
  const travel=P.limitSheetTravel(state.sheet,cfg,trimKey?trimKey*travelLimit:difference,time);
  const crew=difficulty==='easy'?0:crewSideCommand;
  const shift=Number(controlPressed('KeyX'))-Number(controlPressed('KeyZ'));
  if(difficulty==='hard'&&shift&&!state.capsized){
    const tap=pendingTaps.has(shift>0?'KeyX':'KeyZ');
    setForeAftTarget(foreAftTarget+shift*(tap?.5:.9*Sim.fixedDt));
  }
  const foreAft=difficulty==='hard'?foreAftTarget:0;
  const touch=helmPointer===null?pendingTouchSteer:touchSteer;
  return {steer:steeringInput(touch),controlRate:env.controlRate,
    controlSensitivity:env.controlSensitivity,motionDamping:env.motionDamping,steerDigital:touch===null,trimFast,trimKey,
    trim:clamp(travel/travelLimit,-1,1),sheetTarget:trimKey>0?1:trimKey<0?0:sheetTarget,crew,foreAft,crewPose:env.crewPose,difficulty,
