  if(state.recovering||previous.recovering||control.trimKey)sheetTarget=state.sheet;
  if(!live?.fleet?.inWorld)raceEvents(course.update(previous,state,Sim.fixedDt,{nowMs:stepNowMs,discontinuity:!!(state.recovering||previous.recovering||state.capsized||previous.capsized)}));
