startGrid(model, players, largest) {
  const line = model.startLine;
  const width = Math.hypot(line.b.x-line.a.x,line.b.y-line.a.y);
  const tangent = { x:(line.b.x-line.a.x)/width, y:(line.b.y-line.a.y)/width };
