updatePhase() {
  if (this.phase === 'countdown' && [...this.races.values()].some(r=>r.phase!=='countdown')) this.phase = 'race';
  if (this.phase === 'race' && this.races.size && [...this.races.values()].every(r=>r.finished)) this.phase = 'results';
